import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";

// Google Fonts Loader (Standard Pattern)
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema Definition ---


export type LineChartAnimationProps = Record<string, any>;

// --- Helper Components ---

const GridLine: React.FC<{
  y: number;
  label: string;
  width: number;
  color: string;
  opacity: number;
  delay: number;
  frame: number;
  fps: number;
}> = ({ y, label, width, color, opacity, delay, frame, fps }) => {
  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 20 },
  });

  const lineScale = interpolate(progress, [0, 1], [0, 1]);
  const textOpacity = interpolate(progress, [0.5, 1], [0, 1]);

  return (
    <div
      style={{
        position: "absolute",
        top: y,
        left: 0,
        width: "100%",
        display: "flex",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: 40,
          color: color,
          fontSize: 24,
          fontFamily: "Inter",
          fontWeight: 600,
          opacity: textOpacity * opacity,
          textAlign: "right",
          marginRight: 10,
        }}
      >
        {label}
      </div>
      <div
        style={{
          flex: 1,
          height: 1,
          borderTop: `2px dashed ${color}`,
          opacity: 0.2 * lineScale,
          transformOrigin: "left",
          transform: `scaleX(${lineScale})`,
        }}
      />
    </div>
  );
};

// --- Main Component ---
const LineChartAnimation: React.FC<LineChartAnimationProps> = ({
  backgroundColor = "#0D1117",
  transparentBackground = false,
  lineColor = "#40C4FF",
  textColor = "#ffffff",
  amount = 20000.63,
  durationInSeconds = 8,
  showGrid = true,
}) => {
  // Load Fonts
  useFontLoader(["Inter", "Roboto Mono"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Color Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Constants ---
  const chartHeight = width * 0.8; // Square-ish aspect for the chart area
  const chartWidth = width * 0.85;
  const paddingX = (width - chartWidth) / 2;
  const centerY = height * 0.5;
  const chartTop = centerY - chartHeight / 2;

  // --- Path Generation ---
  // We construct a path that matches the wave in the image:
  // Starts low left, bumps up, dips, bumps higher, dips, bumps highest.
  const p = {
    startX: 0,
    startY: chartHeight * 0.9,
    w: chartWidth,
    h: chartHeight,
  };

  // SVG Path Data (Cubic Beziers)
  const dPath = [
    `M ${p.startX} ${p.startY}`, // Start Bottom Left
    `C ${p.w * 0.05} ${p.startY}, ${p.w * 0.1} ${p.h * 0.8}, ${p.w * 0.15} ${p.h * 0.75}`, // First bump
    `S ${p.w * 0.25} ${p.h * 0.85}, ${p.w * 0.35} ${p.h * 0.65}`, // Dip then rise
    `S ${p.w * 0.5} ${p.h * 0.7}, ${p.w * 0.6} ${p.h * 0.5}`, // Dip then rise higher
    `S ${p.w * 0.75} ${p.h * 0.55}, ${p.w * 0.85} ${p.h * 0.3}`, // Dip then rise even higher
    `S ${p.w * 0.95} ${p.h * 0.25}, ${p.w} ${p.h * 0.15}`, // Final peak
  ].join(" ");

  // Closed path for the gradient fill (extends to bottom corners)
  const dFill = [
    dPath,
    `L ${p.w} ${p.h}`, // Line to bottom right
    `L ${0} ${p.h}`, // Line to bottom left
    "Z", // Close
  ].join(" ");

  // --- Animations ---

  // 1. Line Drawing
  const drawDuration = 50; // frames
  const drawStart = 15;
  const drawProgress = spring({
    frame: frame - drawStart,
    fps,
    config: { damping: 100, stiffness: 200, mass: 3 }, // Linear-ish spring for smooth drawing
  });

  // Clamp progress 0-1 for evolvePath
  const clampedDrawProgress = Math.min(Math.max(drawProgress, 0), 1);
  const evolution = evolvePath(clampedDrawProgress, dPath);

  // 2. Fill Reveal (Clip Path Wipe)
  const fillOpacity = interpolate(drawProgress, [0, 1], [0, 0.6]);
  const clipWidth = interpolate(drawProgress, [0, 1], [0, 100]);

  // 3. Counter Animation (Updated to Spring for smoothness)
  const countStart = 10;
  const countSpring = spring({
    frame: frame - countStart,
    fps,
    config: {
      damping: 20,
      stiffness: 55, // Lower stiffness for a gentler, smoother climb
      mass: 1,
    },
  });

  // Clamp the spring value to ensure we don't overshoot the final money amount
  const countProgress = Math.min(Math.max(countSpring, 0), 1);
  
  // Ensure the amount is valid (number) before calculating
  const safeAmount = Number.isFinite(amount) ? amount : 0;
  const currentAmount = safeAmount * countProgress;
  
  // Currency Formatting
  const currencyFormatter = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  });
  
  // Split dollars and cents for styling safely
  const formattedFull = currencyFormatter.format(currentAmount);
  const parts = formattedFull.split(".");
  const dollars = parts[0];
  const cents = parts[1] ?? "00";
  
  // 4. Text Slide Up
  const textY = interpolate(frame, [0, 30], [20, 0], {
    extrapolateRight: "clamp",
    easing: (t) => 1 - Math.pow(1 - t, 3),
  });
  const textOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        color: textColor,
      }}
    >
      {/* Header Section */}
      <div
        style={{
          position: "absolute",
          top: chartTop - 180,
          left: paddingX,
          transform: `translateY(${textY}px)`,
          opacity: textOpacity,
        }}
      >
        <div
          style={{
            fontSize: 90,
            fontWeight: 700,
            display: "flex",
            alignItems: "baseline",
            letterSpacing: -2,
          }}
        >
          <span>{dollars}</span>
          <span
            style={{
              fontSize: 50,
              opacity: 0.6,
              marginLeft: 5,
              fontWeight: 600,
            }}
          >
            .{cents}
          </span>
        </div>
        <div
          style={{
            fontSize: 24,
            fontWeight: 500,
            opacity: 0.5,
            marginTop: 10,
            letterSpacing: 1,
            textTransform: "uppercase",
          }}
        >
          Total Revenue
        </div>
      </div>

      {/* Chart Container */}
      <div
        style={{
          position: "absolute",
          top: chartTop,
          left: paddingX,
          width: chartWidth,
          height: chartHeight,
        }}
      >
        {/* Y-Axis Grid Lines */}
        {showGrid && (
          <>
            <GridLine
              y={chartHeight * 0.25}
              label="20K"
              width={chartWidth}
              color={textColor}
              opacity={0.3}
              delay={5}
              frame={frame}
              fps={fps}
            />
            <GridLine
              y={chartHeight * 0.5}
              label="15K"
              width={chartWidth}
              color={textColor}
              opacity={0.3}
              delay={10}
              frame={frame}
              fps={fps}
            />
            <GridLine
              y={chartHeight * 0.75}
              label="10K"
              width={chartWidth}
              color={textColor}
              opacity={0.3}
              delay={15}
              frame={frame}
              fps={fps}
            />
          </>
        )}

        {/* The SVG Chart */}
        <svg
          width={chartWidth}
          height={chartHeight}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            overflow: "visible",
          }}
        >
          <defs>
            <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={lineColor} stopOpacity={0.5} />
              <stop offset="100%" stopColor={lineColor} stopOpacity={0.0} />
            </linearGradient>
            <clipPath id="revealClip">
              <rect x="0" y="0" width={`${clipWidth}%`} height="100%" />
            </clipPath>
            {/* Glow Filter */}
            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="6" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          {/* Gradient Fill Area */}
          <path
            d={dFill}
            fill="url(#chartGradient)"
            clipPath="url(#revealClip)"
            style={{ opacity: fillOpacity }}
          />

          {/* Animated Stroke Line */}
          <path
            d={dPath}
            fill="none"
            stroke={lineColor}
            strokeWidth={8}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            filter="url(#glow)"
          />
          
          {/* End Point Dot (Visible when drawing completes) */}
          <circle 
            cx={chartWidth} 
            cy={chartHeight * 0.15} 
            r={10} 
            fill={backgroundColor} 
            stroke={lineColor} 
            strokeWidth={4}
            style={{
                opacity: drawProgress >= 0.95 ? (drawProgress - 0.95) * 20 : 0,
                transformBox: 'fill-box',
                transformOrigin: 'center',
                transform: `scale(${drawProgress >= 0.95 ? 1 : 0})`
            }}
          />

        </svg>

        {/* X-Axis Labels */}
        <div
          style={{
            position: "absolute",
            bottom: -40,
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            paddingLeft: 20, // Offset for Y-axis alignment
          }}
        >
          {["JAN", "FEB", "MAR", "APR", "MAY"].map((month, i) => {
            const labelOpacity = interpolate(
              frame - (20 + i * 5),
              [0, 10],
              [0, 0.6],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );
            const labelY = interpolate(
              frame - (20 + i * 5),
              [0, 10],
              [10, 0],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );
            return (
              <span
                key={month}
                style={{
                  color: textColor,
                  fontSize: 20,
                  fontWeight: 600,
                  opacity: labelOpacity,
                  transform: `translateY(${labelY}px)`,
                }}
              >
                {month}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LineChartAnimation;